CREATE TABLE IF NOT EXISTS bank_journal_reconciliation_links (
  id INTEGER PRIMARY KEY,
  bank_transaction_id INTEGER NOT NULL REFERENCES bank_transactions(id),
  journal_entry_id INTEGER NOT NULL REFERENCES journal_entries(id),
  match_method TEXT NOT NULL CHECK(match_method IN ('exact-date-amount','settlement-lag-amount','source-reference','manual-review')),
  source_reference TEXT,
  note TEXT,
  created_by TEXT NOT NULL,
  created_by_program TEXT NOT NULL DEFAULT 'rentemester',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(bank_transaction_id),
  UNIQUE(bank_transaction_id, journal_entry_id),
  CHECK(source_reference IS NULL OR length(trim(source_reference)) > 0),
  CHECK(note IS NULL OR length(trim(note)) > 0)
);
CREATE TRIGGER bank_journal_reconciliation_links_guard_insert BEFORE INSERT ON bank_journal_reconciliation_links WHEN NOT EXISTS (SELECT 1 FROM bank_transactions bt JOIN bank_accounts ba ON ba.id = bt.bank_account_id WHERE bt.id = NEW.bank_transaction_id AND ba.ledger_account_no IS NOT NULL) OR NOT EXISTS (SELECT 1 FROM journal_entries je WHERE je.id = NEW.journal_entry_id AND je.status = 'posted' AND je.reversal_of_entry_id IS NULL) OR EXISTS (SELECT 1 FROM journal_entries je WHERE je.source_bank_transaction_id = NEW.bank_transaction_id) OR EXISTS (SELECT 1 FROM journal_entries je WHERE je.id = NEW.journal_entry_id AND je.source_bank_transaction_id IS NOT NULL) OR EXISTS (SELECT 1 FROM journal_entries reversal WHERE reversal.reversal_of_entry_id = NEW.journal_entry_id) OR NOT EXISTS (SELECT 1 FROM bank_transactions bt JOIN bank_accounts ba ON ba.id = bt.bank_account_id JOIN accounts a ON a.account_no = ba.ledger_account_no JOIN journal_lines jl ON jl.account_id = a.id AND jl.journal_entry_id = NEW.journal_entry_id WHERE bt.id = NEW.bank_transaction_id GROUP BY bt.id HAVING CAST(ROUND(100 * SUM(jl.debit_amount - jl.credit_amount)) AS INTEGER) = CAST(ROUND(100 * CASE WHEN UPPER(bt.currency) = 'DKK' THEN bt.amount ELSE bt.amount_dkk END) AS INTEGER)) BEGIN SELECT RAISE(ABORT, 'bank-journal reconciliation link requires an active unlinked journal whose mapped-bank movement equals the bank transaction in DKK'); END;
CREATE TRIGGER bank_journal_reconciliation_links_no_update BEFORE UPDATE ON bank_journal_reconciliation_links BEGIN SELECT RAISE(ABORT, 'bank-journal reconciliation links are append-only'); END;
CREATE TRIGGER bank_journal_reconciliation_links_no_delete BEFORE DELETE ON bank_journal_reconciliation_links BEGIN SELECT RAISE(ABORT, 'bank-journal reconciliation links are append-only'); END;
CREATE TRIGGER journal_entries_bank_reconciliation_link_conflict BEFORE INSERT ON journal_entries WHEN NEW.source_bank_transaction_id IS NOT NULL AND EXISTS (SELECT 1 FROM bank_journal_reconciliation_links link WHERE link.bank_transaction_id = NEW.source_bank_transaction_id) BEGIN SELECT RAISE(ABORT, 'bank transaction already has an append-only reconciliation link'); END;
DROP TRIGGER IF EXISTS bank_transactions_no_update_when_referenced;
CREATE TRIGGER bank_transactions_no_update_when_referenced BEFORE UPDATE ON bank_transactions WHEN EXISTS(SELECT 1 FROM journal_entries WHERE source_bank_transaction_id = OLD.id) OR EXISTS(SELECT 1 FROM bank_journal_reconciliation_links WHERE bank_transaction_id = OLD.id) OR EXISTS(SELECT 1 FROM invoice_payments WHERE bank_transaction_id = OLD.id) OR EXISTS(SELECT 1 FROM invoice_refunds WHERE bank_transaction_id = OLD.id) OR EXISTS(SELECT 1 FROM invoice_claim_payments WHERE bank_transaction_id = OLD.id) BEGIN SELECT RAISE(ABORT, 'bank transaction is referenced by ledger, reconciliation, or payment records and cannot be modified'); END;
CREATE VIEW IF NOT EXISTS bank_journal_reconciliations AS SELECT je.source_bank_transaction_id AS bank_transaction_id, je.id AS journal_entry_id, je.entry_no AS journal_entry_no, 'direct' AS link_kind FROM journal_entries je WHERE je.source_bank_transaction_id IS NOT NULL AND je.status = 'posted' UNION ALL SELECT link.bank_transaction_id, je.id, je.entry_no, 'append-only' FROM bank_journal_reconciliation_links link JOIN journal_entries je ON je.id = link.journal_entry_id WHERE je.status = 'posted';
